def normalize_messages(messages):
    result = []
    for message in messages:
        if not isinstance(message, dict):
            raise HTTPException(422, "Érvénytelen üzenet.")
        role = message.get("role")
        if role not in {"system", "user", "assistant", "tool", "function"}:
            raise HTTPException(422, "Érvénytelen üzenetszerep.")
        content = message.get("content", "")
        if isinstance(content, list):
            parts = []
            for part in content:
                if not isinstance(part, dict):
                    continue
                if part.get("type") in {"text", "input_text"}:
                    parts.append({"type": "text", "text": str(part.get("text", ""))})
                elif part.get("type") in {"image_url", "input_image"}:
                    source = part.get("image_url", part.get("image_url", part.get("url")))
                    if isinstance(source, dict):
                        source = source.get("url")
                    if source:
                        parts.append({"type": "image_url", "image_url": {"url": source}})
                elif part.get("type") in {"text_file", "file"} and "text" in part:
                    parts.append(
                        {
                            "type": "text",
                            "text": str(part.get("name", "Csatolt fájl"))
                            + "\n"
                            + str(part["text"]),
                        }
                    )
            content = parts
        item = {"role": role, "content": content}
        for key in ("name", "tool_call_id", "tool_calls", "function_call"):
            if key in message:
                item[key] = message[key]
        result.append(item)
    if not result:
        raise HTTPException(422, "Legalább egy üzenet szükséges.")
    return result


