class MCPConnection:
    def __init__(self, name, configuration):
        self.name = name
        self.url = configuration["url"]
        self.headers = dict(configuration.get("headers", {}))
        self.session_id = None
        self.sequence = 0
        self.lock = asyncio.Lock()
        self.tools = []

    async def request(self, method, parameters=None, notification=False):
        async with self.lock:
            self.sequence += 1
            payload = {"jsonrpc": "2.0", "method": method}
            if parameters is not None:
                payload["params"] = parameters
            if not notification:
                payload["id"] = self.sequence
            headers = {
                "Accept": "application/json, text/event-stream",
                "Content-Type": "application/json",
                **self.headers,
            }
            if self.session_id:
                headers["Mcp-Session-Id"] = self.session_id
                headers["MCP-Protocol-Version"] = "2025-03-26"
            async with HTTP.stream(
                "POST", self.url, json=payload, headers=headers, timeout=None
            ) as response:
                response.raise_for_status()
                received_session = response.headers.get("Mcp-Session-Id")
                if received_session:
                    self.session_id = received_session
                if notification or response.status_code == 202:
                    await response.aread()
                    return {}
                if "text/event-stream" in response.headers.get("content-type", ""):
                    data_lines = []
                    async for line in response.aiter_lines():
                        if line.startswith("data:"):
                            data_lines.append(line[5:].lstrip())
                        elif not line and data_lines:
                            message = json.loads("\n".join(data_lines))
                            data_lines = []
                            if message.get("id") == payload["id"]:
                                if "error" in message:
                                    raise RuntimeError(encode(message["error"]))
                                return message.get("result", {})
                    raise RuntimeError("A kapcsolt alkalmazás válaszfolyama lezárult.")
                body = json.loads(await response.aread())
                if "error" in body:
                    raise RuntimeError(encode(body["error"]))
                return body.get("result", {})

    async def initialize(self):
        await self.request(
            "initialize",
            {
                "protocolVersion": "2025-03-26",
                "capabilities": {},
                "clientInfo": {"name": "work-agent", "version": "1.0.0"},
            },
        )
        await self.request("notifications/initialized", notification=True)
        cursor = None
        collected = []
        while True:
            result = await self.request(
                "tools/list", {"cursor": cursor} if cursor else {}
            )
            collected.extend(result.get("tools", []))
            cursor = result.get("nextCursor")
            if not cursor:
                break
        self.tools = collected

    async def call(self, name, arguments):
        return await self.request(
            "tools/call", {"name": name, "arguments": arguments}
        )


def execution_output(result):
    if isinstance(result, str):
        return result
    if not isinstance(result, dict):
        raise RuntimeError("Az InstaVM érvénytelen végrehajtási választ adott.")
    if result.get("success") is False or result.get("error"):
        raise RuntimeError(str(result.get("error") or result))
    exit_code = result.get("exit_code", result.get("returncode", 0))
    output = result.get("output", result.get("stdout", ""))
    if isinstance(output, dict):
        output = output.get("stdout", output.get("output", encode(output)))
    if exit_code not in (0, None):
        raise RuntimeError(
            str(result.get("stderr") or output or "Sandbox végrehajtási hiba.")
        )
    return str(output or "")


async def new_vm_session(conversation_id):
    response = await HTTP.post(
        INSTAVM_BASE_URL.rstrip("/") + "/v1/sessions/session",
        headers={"Authorization": "Bearer " + os.environ["INSTAVM_API_KEY"]},
        json={
            "api_key": os.environ["INSTAVM_API_KEY"],
            "vm_lifetime_seconds": 86400,
            "memory_mb": int(os.environ.get("INSTAVM_MEMORY_MB", "2048")),
            "vcpu_count": int(os.environ.get("INSTAVM_VCPU_COUNT", "2")),
        },
        timeout=None,
    )
    response.raise_for_status()
    body = response.json()
    session_id = body.get("session_id")
    if not session_id and isinstance(body.get("session"), dict):
        session_id = body["session"].get("session_id", body["session"].get("id"))
    if not session_id:
        raise RuntimeError("Az InstaVM nem adott vissza session_id értéket.")
    with DB:
        execute(
            "UPDATE conversations SET sandbox_id=?,updated=? WHERE id=?",
            (session_id, timestamp(), conversation_id),
        )
    return session_id


def construct_vm(session_id):
    options = {
        "api_key": os.environ["INSTAVM_API_KEY"],
        "base_url": INSTAVM_BASE_URL,
        "timeout": 300,
        "max_retries": 0,
    }
    signature = inspect.signature(InstaVM)
    parameters = signature.parameters
    if "session_id" in parameters:
        options["session_id"] = session_id
        return InstaVM(**options)
    client = InstaVM(**options)
    allocated_session = getattr(client, "session_id", None)
    if allocated_session and allocated_session != session_id:
        client.close_session()
    if hasattr(client, "_session_id"):
        client._session_id = session_id
    descriptor = inspect.getattr_static(type(client), "session_id", None)
    if isinstance(descriptor, property) and descriptor.fset is None:
        if not hasattr(client, "_session_id"):
            raise RuntimeError(
                "A telepített InstaVM SDK nem támogatja a meglévő session visszacsatolását."
            )
    else:
        client.session_id = session_id
    return client


async def get_vm(conversation_id):
    if conversation_id in VM_CLIENTS:
        return VM_CLIENTS[conversation_id]
    conversation = require_conversation(conversation_id)
    session_id = conversation["sandbox_id"]
    if session_id:
        response = await HTTP.get(
            INSTAVM_BASE_URL.rstrip("/")
            + "/v1/sessions/status/"
            + quote(session_id, safe=""),
            headers={"Authorization": "Bearer " + os.environ["INSTAVM_API_KEY"]},
            timeout=None,
        )
        if response.status_code == 404:
            raise RuntimeError(
                "A beszélgetés InstaVM sandboxa lejárt. "
                "A megőrzött eredmények továbbra is elérhetők; új sandboxhoz indíts új beszélgetést."
            )
        response.raise_for_status()
        status = response.json()
        if (
            status.get("alive") is False
            or status.get("is_alive") is False
            or status.get("active") is False
            or status.get("status") in {"killed", "terminated", "expired"}
        ):
            raise RuntimeError(
                "A beszélgetés InstaVM sandboxa már nem aktív. "
                "Új sandboxhoz indíts új beszélgetést."
            )
    else:
        session_id = await new_vm_session(conversation_id)
    client = await asyncio.to_thread(construct_vm, session_id)
    await asyncio.to_thread(
        client.execute,
        "import pathlib\npathlib.Path('/app/workspace').mkdir(parents=True, exist_ok=True)\nprint('ready')",
        language="python",
    )
    VM_CLIENTS[conversation_id] = client
    return client


async def remote_python(conversation_id, code):
    lock = VM_LOCKS.setdefault(conversation_id, asyncio.Lock())
    async with lock:
        client = await get_vm(conversation_id)
        result = await asyncio.to_thread(client.execute, code, language="python")
        return execution_output(result)


async def remote_json(conversation_id, code):
    output = await remote_python(conversation_id, code)
    marker = "__WORK_RESULT__"
    position = output.rfind(marker)
    if position < 0:
        raise RuntimeError("A sandbox nem adott vissza feldolgozható eredményt: " + output)
    return json.loads(output[position + len(marker):].strip())


