        f"  stream.seek({int(offset)})\n"
        "  chunk=stream.read(65536)\n"
        "state['output']=base64.b64encode(chunk).decode()\n"
        f"state['offset']={int(offset)}+len(chunk)\n"
        "state['has_more']=output.exists() and output.stat().st_size>state['offset']\n"
        "print('__WORK_RESULT__'+json.dumps(state))"
