    existing = row(
        "SELECT * FROM executions WHERE id=? AND job_id=?", (execution_id, job_id)
    )
    if existing and existing["result"] is not None:
        return decode(existing["result"])
    if not existing:
        with DB:
            execute(
                "INSERT INTO executions(id,job_id,offset,output,result) VALUES(?,?,0,'',NULL)",
                (execution_id, job_id),
            )
    await launch_execution(conversation_id, execution_id, argv, cwd)
    while True:
        if require_job(job_id)["cancel_requested"]:
            await execution_cancel(conversation_id, execution_id)
            raise asyncio.CancelledError
        execution = row("SELECT * FROM executions WHERE id=?", (execution_id,))
        result = await execution_poll(
            conversation_id, execution_id, execution["offset"]
        )
        chunk = base64.b64decode(result.get("output", "")).decode("utf-8", "replace")
        if chunk:
            with DB:
                execute(
                    "UPDATE executions SET offset=?,output=output||? WHERE id=?",
                    (result["offset"], chunk, execution_id),
                )
                execute(
                    "INSERT INTO events(job_id,payload,created) VALUES(?,?,?)",
                    (
                        job_id,
                        encode(
                            {
                                "type": "agent_event",
                                "event": {
                                    "type": "tool_output",
                                    "execution_id": execution_id,
                                    "content": chunk,
                                },
                            }
                        ),
                        timestamp(),
                    ),
                )
        if result["status"] in {"completed", "failed"} and not result["has_more"]:
            execution = row("SELECT * FROM executions WHERE id=?", (execution_id,))
            final = {
                "exit_code": result.get("exit_code"),
                "output": execution["output"],
                "error": result.get("error"),
                "ok": result["status"] == "completed"
                and result.get("exit_code") == 0,
            }
            with DB:
                execute(
                    "UPDATE executions SET result=? WHERE id=?",
                    (encode(final), execution_id),
                )
            return final
        await asyncio.sleep(0.5)


async def pull_file(conversation_id, remote_path, local_path):
    metadata = await remote_json(
        conversation_id,
        "import json,pathlib\n"
        f"p=pathlib.Path({remote_path!r})\n"
        "if not p.is_file():\n"
        " raise FileNotFoundError(str(p))\n"
        "print('__WORK_RESULT__'+json.dumps({'size':p.stat().st_size,'name':p.name}))",
    )
    local_path.parent.mkdir(parents=True, exist_ok=True)
    offset = 0
    with local_path.open("wb") as destination:
        while offset < metadata["size"]:
            result = await remote_json(
                conversation_id,
                "import base64,json\n"
                f"with open({remote_path!r},'rb') as stream:\n"
                f" stream.seek({offset})\n"
                " chunk=stream.read(786432)\n"
                "print('__WORK_RESULT__'+json.dumps({'data':base64.b64encode(chunk).decode()}))",
            )
            chunk = base64.b64decode(result["data"])
            if not chunk:
                raise RuntimeError("A sandbox fájlja letöltés közben váratlanul lezárult.")
            destination.write(chunk)
            offset += len(chunk)
    if local_path.stat().st_size != metadata["size"]:
        raise RuntimeError("A letöltött fájl mérete nem egyezik az eredetivel.")
    return metadata


async def push_file(conversation_id, local_path, remote_path):
    lock = VM_LOCKS.setdefault(conversation_id, asyncio.Lock())
    async with lock:
        client = await get_vm(conversation_id)
        await asyncio.to_thread(client.upload_file, str(local_path), remote_path)


def infer_kind(path):
    suffix = Path(path).suffix.lower()
    return {
        ".docx": "document",
        ".odt": "document",
        ".xlsx": "spreadsheet",
        ".ods": "spreadsheet",
        ".csv": "spreadsheet",
        ".pptx": "presentation",
        ".odp": "presentation",
        ".pdf": "report",
        ".html": "site",
        ".htm": "site",
    }.get(suffix, "file")


def validate_artifact(path):
    suffix = path.suffix.lower()
    if suffix in {".docx", ".xlsx", ".pptx"}:
        required = {
            ".docx": "word/document.xml",
            ".xlsx": "xl/workbook.xml",
            ".pptx": "ppt/presentation.xml",
        }[suffix]
        with zipfile.ZipFile(path) as archive:
            if required not in archive.namelist():
                raise RuntimeError("A létrehozott Office-fájl formátuma érvénytelen.")
    elif suffix == ".pdf":
        with path.open("rb") as stream:
            if stream.read(5) != b"%PDF-":
                raise RuntimeError("A létrehozott PDF formátuma érvénytelen.")


async def publish_artifact(job_id, path, name=None, kind=None):
    job = require_job(job_id)
    conversation_id = job["conversation_id"]
    existing = row(
        "SELECT id FROM artifacts WHERE job_id=? AND remote_path=?",
        (job_id, path),
    )
    if existing:
        return next(
            artifact
            for artifact in artifacts_for(job_id)
            if artifact["id"] == existing["id"]
        )
    artifact_id = identifier()
    display_name = name or Path(path).name
    kind = kind or infer_kind(path)
    extension = Path(path).suffix
    destination = ARTIFACT_ROOT / artifact_id / ("artifact" + extension)
    await pull_file(conversation_id, path, destination)
    validate_artifact(destination)
    site_root = None
    if kind == "site":
        site_root = ARTIFACT_ROOT / artifact_id / "site"
        directory = str(Path(path).parent)
        manifest = await remote_json(
            conversation_id,
            "import json,pathlib\n"
            f"root=pathlib.Path({directory!r}).resolve()\n"
            "files=[str(p.relative_to(root)) for p in root.rglob('*') if p.is_file()]\n"
            "print('__WORK_RESULT__'+json.dumps({'files':files}))",
        )
        for relative_name in manifest["files"]:
            destination_file = site_root / relative_name
            await pull_file(
                conversation_id,
                directory + "/" + relative_name,
                destination_file,
            )
        source_index = site_root / Path(path).name
        index = site_root / "index.html"
        if source_index != index:
            index.write_bytes(source_index.read_bytes())
    mime = mimetypes.guess_type(display_name)[0]
    if not mime:
        mime = mimetypes.guess_type(str(destination))[0] or "application/octet-stream"
    with DB:
        execute(
            "INSERT INTO artifacts"
            "(id,job_id,conversation_id,name,kind,mime,path,remote_path,site_root,size,created)"
            " VALUES(?,?,?,?,?,?,?,?,?,?,?)",
            (
                artifact_id,
                job_id,
                conversation_id,
                display_name,
                kind,
                mime,
                str(destination),
                path,
                str(site_root) if site_root else None,
                destination.stat().st_size,
                timestamp(),
            ),
        )
    artifact = next(
        item for item in artifacts_for(job_id) if item["id"] == artifact_id
    )
    agent_event(job_id, "artifact", artifact=artifact)
    return artifact


ARTIFACT_GENERATOR = r"""
import importlib
import json
import pathlib
import subprocess
import sys
from xml.sax.saxutils import escape

request = json.loads(sys.argv[1])
kind = request["kind"]
data = request["data"]
destination = pathlib.Path(request["path"])
destination.parent.mkdir(parents=True, exist_ok=True)

def dependency(module, package):
    try:
        return importlib.import_module(module)
    except ModuleNotFoundError:
        subprocess.check_call([sys.executable, "-m", "pip", "install", package])
        return importlib.import_module(module)

if kind == "document":
    docx = dependency("docx", "python-docx")
    document = docx.Document()
    if data.get("title"):
        document.add_heading(str(data["title"]), 0)
    for paragraph in data.get("paragraphs", []):
        if isinstance(paragraph, dict):
            if paragraph.get("heading"):
                document.add_heading(str(paragraph["heading"]), int(paragraph.get("level", 1)))
            if "text" in paragraph:
                document.add_paragraph(str(paragraph["text"]))
        else:
            document.add_paragraph(str(paragraph))
    for specification in data.get("tables", []):
        matrix = specification.get("rows", []) if isinstance(specification, dict) else specification
        if matrix:
            table = document.add_table(rows=1, cols=max(len(row) for row in matrix))
            table.style = "Table Grid"
            for index, values in enumerate(matrix):
                cells = table.rows[0].cells if index == 0 else table.add_row().cells
                for column, value in enumerate(values):
                    cells[column].text = str(value)
    document.save(destination)
elif kind == "spreadsheet":
    openpyxl = dependency("openpyxl", "openpyxl")
    workbook = openpyxl.Workbook()
    workbook.remove(workbook.active)
    specifications = data.get("sheets", [])
    if not specifications:
        raise ValueError("A spreadsheet requires at least one sheet.")
    for specification in specifications:
        sheet = workbook.create_sheet(str(specification.get("name", "Sheet"))[:31])
        for values in specification.get("rows", []):
            sheet.append(values)
        if specification.get("freeze_panes"):
            sheet.freeze_panes = specification["freeze_panes"]
        if specification.get("auto_filter") and sheet.max_row and sheet.max_column:
            sheet.auto_filter.ref = sheet.dimensions
        for column, width in specification.get("column_widths", {}).items():
            sheet.column_dimensions[column].width = float(width)
        for cell, format_string in specification.get("number_formats", {}).items():
            sheet[cell].number_format = format_string
    workbook.save(destination)
elif kind == "presentation":
    pptx = dependency("pptx", "python-pptx")
    presentation = pptx.Presentation()
    for specification in data.get("slides", []):
        slide = presentation.slides.add_slide(presentation.slide_layouts[1])
        slide.shapes.title.text = str(specification.get("title", ""))
        body = specification.get("body", [])
        frame = slide.placeholders[1].text_frame
        frame.clear()
        paragraphs = body if isinstance(body, list) else str(body).splitlines()
        for index, paragraph in enumerate(paragraphs):
            item = frame.paragraphs[0] if index == 0 else frame.add_paragraph()
            if isinstance(paragraph, dict):
                item.text = str(paragraph.get("text", ""))
                item.level = int(paragraph.get("level", 0))
            else:
                item.text = str(paragraph)
        if specification.get("notes"):
            slide.notes_slide.notes_text_frame.text = str(specification["notes"])
    if not presentation.slides:
        raise ValueError("A presentation requires at least one slide.")
    presentation.save(destination)
elif kind == "report":
    dependency("reportlab", "reportlab")
    dependency("matplotlib", "matplotlib")
    import matplotlib
    from reportlab.lib import colors
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.units import cm
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle
    font = pathlib.Path(matplotlib.get_data_path()) / "fonts" / "ttf" / "DejaVuSans.ttf"
    pdfmetrics.registerFont(TTFont("DocumentFont", str(font)))
    body = ParagraphStyle("Body", fontName="DocumentFont", fontSize=10, leading=15)
    heading = ParagraphStyle("Heading", fontName="DocumentFont", fontSize=18, leading=24, spaceAfter=15)
    story = []
    if data.get("title"):
        story.append(Paragraph(escape(str(data["title"])), heading))
    for paragraph in data.get("paragraphs", []):
        if isinstance(paragraph, dict):
            if paragraph.get("heading"):
                story.append(Paragraph(escape(str(paragraph["heading"])), heading))
            text = str(paragraph.get("text", ""))
        else:
            text = str(paragraph)
        story.append(Paragraph(escape(text).replace("\n", "<br/>"), body))
        story.append(Spacer(1, 0.25 * cm))
    for specification in data.get("tables", []):
        matrix = specification.get("rows", []) if isinstance(specification, dict) else specification
        if matrix:
            rendered = [[Paragraph(escape(str(value)), body) for value in values] for values in matrix]
            table = Table(rendered, repeatRows=1)
            table.setStyle(TableStyle([
                ("GRID", (0, 0), (-1, -1), 0.5, colors.grey),
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#eeeeee")),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ]))
            story.append(table)
            story.append(Spacer(1, 0.4 * cm))
    SimpleDocTemplate(str(destination)).build(story)
elif kind == "site":
    markup = data.get("html")
    if not isinstance(markup, str) or not markup.strip():
        raise ValueError("A Site requires complete HTML content.")
    destination.write_text(markup, encoding="utf-8")
    for filename, content in data.get("assets", {}).items():
        target = destination.parent / filename
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(str(content), encoding="utf-8")
else:
    raise ValueError("Unknown artifact kind.")

if not destination.is_file() or destination.stat().st_size == 0:
    raise RuntimeError("Artifact generation did not produce a non-empty file.")
print(json.dumps({"path": str(destination), "size": destination.stat().st_size}))
"""


def parse_run_at(value):
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except (TypeError, ValueError) as error:
        raise HTTPException(422, "Érvénytelen ISO 8601 időpont.") from error
    if parsed.tzinfo is None:
        raise HTTPException(422, "Az időpontnak időzónát is tartalmaznia kell.")
    return parsed.timestamp()


def create_schedule_record(arguments):
    interval = arguments.get("interval_seconds")
    if interval is not None and float(interval) <= 0:
        raise HTTPException(422, "Az ismétlési időköznek pozitívnak kell lennie.")
    schedule_id = identifier()
    with DB:
        execute(
            "INSERT INTO schedules(id,title,prompt,next_run,interval_seconds,enabled)"
            " VALUES(?,?,?,?,?,1)",
            (
                schedule_id,
                arguments.get("title", arguments["prompt"][:100]),
                arguments["prompt"],
                parse_run_at(arguments["run_at"]),
                float(interval) if interval is not None else None,
            ),
        )
    return row("SELECT * FROM schedules WHERE id=?", (schedule_id,))


def create_trigger_record(arguments):
    name = arguments["name"].strip()
    if not name:
        raise HTTPException(422, "A trigger neve nem lehet üres.")
    trigger_id = identifier()
    with DB:
        execute(
            "INSERT INTO triggers(id,name,title,prompt) VALUES(?,?,?,?)",
            (
                trigger_id,
                name,
                arguments.get("title", name),
                arguments["prompt"],
            ),
        )
    return {
        "id": trigger_id,
        "name": name,
        "endpoint": "/api/triggers/" + quote(name, safe=""),
    }


async def perform_tool(job_id, call):
    job = require_job(job_id)
    conversation_id = job["conversation_id"]
    name = call["name"]
    arguments = json.loads(call["arguments"] or "{}")
    execution_id = call["id"]
    if name == "shell":
        return await execute_remote_command(
            job_id,
            execution_id,
            ["/bin/bash", "-lc", arguments["command"]],
            arguments.get("cwd", WORKSPACE),
        )
    if name == "python":
        return await execute_remote_command(
            job_id,
            execution_id,
            ["python3", "-u", "-c", arguments["code"]],
            arguments.get("cwd", WORKSPACE),
        )
    if name == "read_file":
        path = arguments["path"]
        encoding = arguments.get("encoding", "utf-8")
        return await remote_json(
            conversation_id,
            "import base64,json,pathlib\n"
            f"data=pathlib.Path({path!r}).read_bytes()\n"
            f"content=base64.b64encode(data).decode() if {encoding!r}=='base64' "
            "else data.decode('utf-8')\n"
            "print('__WORK_RESULT__'+json.dumps({'content':content,'size':len(data)}))",
        )
    if name == "write_file":
        path = arguments["path"]
        content = arguments["content"]
        encoding = arguments.get("encoding", "utf-8")
        return await remote_json(
            conversation_id,
            "import base64,json,pathlib\n"
            f"path=pathlib.Path({path!r})\n"
            "path.parent.mkdir(parents=True,exist_ok=True)\n"
            f"data=base64.b64decode({content!r}) if {encoding!r}=='base64' "
            f"else {content!r}.encode('utf-8')\n"
            "path.write_bytes(data)\n"
            "print('__WORK_RESULT__'+json.dumps({'path':str(path),'size':len(data)}))",
        )
    if name == "publish_artifact":
        return await publish_artifact(
            job_id,
            arguments["path"],
            arguments.get("name"),
            arguments.get("kind"),
        )
    if name == "create_artifact":
        kind = arguments["kind"]
        extension = {
            "document": ".docx",
            "spreadsheet": ".xlsx",
            "presentation": ".pptx",
            "report": ".pdf",
            "site": ".html",
        }[kind]
        name_value = Path(arguments["name"]).name
        if not name_value.lower().endswith(extension):
            name_value += extension
        directory = WORKSPACE + "/artifacts/" + execution_id
        remote_path = directory + ("/index.html" if kind == "site" else "/" + name_value)
        request = {"kind": kind, "data": arguments["data"], "path": remote_path}
        result = await execute_remote_command(
            job_id,
            execution_id,
            ["python3", "-u", "-c", ARTIFACT_GENERATOR, encode(request)],
            WORKSPACE,
        )
        if not result["ok"]:
            return result
        return await publish_artifact(job_id, remote_path, name_value, kind)
    if name == "progress":
        agent_event(
            job_id,
            "progress",
            title=arguments["title"],
            result=arguments.get("result", ""),
        )
        return {"published": True}
    if name == "schedule_work":
        return create_schedule_record(arguments)
    if name == "create_trigger":
        return create_trigger_record(arguments)
    if name in MCP_TOOLS:
        connection_name, remote_name = MCP_TOOLS[name]
        return await MCP_CLIENTS[connection_name].call(remote_name, arguments)
    raise RuntimeError("Ismeretlen eszköz: " + name)


def available_functions():
    definitions = list(LOCAL_TOOLS)
    for function_name, (connection_name, remote_name) in MCP_TOOLS.items():
        connection = MCP_CLIENTS[connection_name]
        specification = next(
            tool for tool in connection.tools if tool["name"] == remote_name
        )
        definitions.append(
            {
                "name": function_name,
                "description": specification.get("description", remote_name),
                "parameters": specification.get(
                    "inputSchema", {"type": "object", "properties": {}}
                ),
            }
        )
    return definitions


def apply_redirections(job_id, state):
    pending = rows(
        "SELECT id,content FROM redirections WHERE job_id=? AND consumed=0 ORDER BY id",
        (job_id,),
    )
    if not pending:
        return False
    job = require_job(job_id)
    context = decode(job["context"], [])
    with DB:
        for direction in pending:
            message = {"role": "user", "content": direction["content"]}
            state["messages"].append(message)
            context.append(message)
            execute(
                "UPDATE redirections SET consumed=1 WHERE id=?", (direction["id"],)
            )
        execute(
            "UPDATE jobs SET context=?,state=?,updated=? WHERE id=?",
            (encode(context), encode(state), timestamp(), job_id),
        )
    return True


async def stream_model(job_id, state):
    job = require_job(job_id)
    base_text = job["text"]
    base_reasoning = job["reasoning"]
    state["phase"] = "streaming"
    state["base_text"] = base_text
    state["base_reasoning"] = base_reasoning
    set_state(job_id, state)
    agent_event(job_id, "model_start", model=MODEL)
    content = ""
    function_name = ""
    function_arguments = ""
    modern_calls = {}
    finish_reason = None
    stream = await LLM.chat.completions.create(
        model=MODEL,
        temperature=1,
        top_p=1,
        max_tokens=120000,
        reasoning_effort="max",
        messages=state["messages"],
        functions=available_functions(),
        function_call="auto",
        stream=True,
        extra_body={
            "include_reasoning": True,
            "web_search_options": {"search_context_size": "medium"},
        },
    )
    async with stream:
        async for chunk in stream:
            if require_job(job_id)["cancel_requested"]:
                raise asyncio.CancelledError
            if not chunk.choices:
                continue
            choice = chunk.choices[0]
            delta = choice.delta
            values = delta.model_dump(exclude_none=True)
            text = values.get("content", "")
            reasoning = values.get("reasoning_content", values.get("reasoning", ""))
            if not isinstance(text, str):
                text = ""
            if not isinstance(reasoning, str):
                reasoning = ""
            content += text
            append_delta(job_id, text, reasoning)
            legacy = values.get("function_call")
            if legacy:
                function_name += legacy.get("name", "")
                function_arguments += legacy.get("arguments", "")
            for fragment in values.get("tool_calls", []):
                index = fragment.get("index", 0)
                accumulated = modern_calls.setdefault(
                    index,
                    {"id": "", "name": "", "arguments": "", "modern": True},
                )
                accumulated["id"] += fragment.get("id", "")
                function = fragment.get("function", {})
                accumulated["name"] += function.get("name", "")
                accumulated["arguments"] += function.get("arguments", "")
            if choice.finish_reason:
                finish_reason = choice.finish_reason
    if finish_reason == "length":
        raise RuntimeError("A modell kimenete a szolgáltatói tokenhatárnál megszakadt.")
    if finish_reason == "content_filter":
        raise RuntimeError("A modellszolgáltató nem fejezte be a választ.")
    calls = []
    if function_name:
        calls.append(
            {
                "id": identifier(),
                "name": function_name,
                "arguments": function_arguments,
                "modern": False,
            }
        )
        state["messages"].append(
            {
                "role": "assistant",
                "content": content or None,
                "function_call": {
                    "name": function_name,
                    "arguments": function_arguments,
                },
            }
        )
    elif modern_calls:
        calls = [modern_calls[index] for index in sorted(modern_calls)]
        for call in calls:
            if not call["id"]:
                call["id"] = identifier()
        state["messages"].append(
            {
                "role": "assistant",
                "content": content or None,
                "tool_calls": [
                    {
                        "id": call["id"],
                        "type": "function",
                        "function": {
                            "name": call["name"],
                            "arguments": call["arguments"],
                        },
                    }
                    for call in calls
                ],
            }
        )
    else:
        state["messages"].append({"role": "assistant", "content": content})
    if not calls and not content:
        raise RuntimeError("A modell üres választ adott.")
    state["calls"] = calls
    state["call_index"] = 0
    state["phase"] = "tools" if calls else "final"
    set_state(job_id, state)
    agent_event(job_id, "model_output")
    return bool(calls)


async def cancel_remote_executions(job_id):
    job = require_job(job_id)
    running = rows(
        "SELECT id FROM executions WHERE job_id=? AND result IS NULL", (job_id,)
    )
    for execution in running:
        with contextlib.suppress(Exception):
            await execution_cancel(job["conversation_id"], execution["id"])


async def run_job(job_id):
    job = require_job(job_id)
    lock = CONVERSATION_LOCKS.setdefault(job["conversation_id"], asyncio.Lock())
    try:
        async with lock:
            job = require_job(job_id)
            if job["cancel_requested"]:
                finish_job(job_id, "cancelled")
                return
            with DB:
                execute(
                    "UPDATE jobs SET status='running',updated=? WHERE id=?",
                    (timestamp(), job_id),
                )
            event(job_id, {"type": "status", "status": "running"})
            state = decode(job["state"], None)
            if state is None:
                state = {
                    "messages": [
                        {"role": "system", "content": SYSTEM_MESSAGE},
                        *decode(job["context"], []),
                    ],
                    "phase": "model",
                    "calls": [],
                    "call_index": 0,
                }
                set_state(job_id, state)
            if state["phase"] == "streaming":
                with DB:
                    execute(
                        "UPDATE jobs SET text=?,reasoning=?,updated=? WHERE id=?",
                        (
                            state["base_text"],
                            state["base_reasoning"],
                            timestamp(),
                            job_id,
                        ),
                    )
                state["phase"] = "model"
                set_state(job_id, state)
                event(
                    job_id,
                    {
                        "type": "reset",
                        "content": state["base_text"],
                        "reasoning_content": state["base_reasoning"],
                    },
                )
            await get_vm(job["conversation_id"])
            uploads = rows(
                "SELECT * FROM uploads WHERE conversation_id=? AND uploaded=0 ORDER BY created",
                (job["conversation_id"],),
            )
            for upload in uploads:
                await remote_python(
                    job["conversation_id"],
                    "import pathlib\npathlib.Path('/app/workspace/uploads').mkdir(parents=True,exist_ok=True)\nprint('ready')",
                )
                await push_file(
                    job["conversation_id"], Path(upload["path"]), upload["remote_path"]
                )
                with DB:
                    execute("UPDATE uploads SET uploaded=1 WHERE id=?", (upload["id"],))
            while True:
                if require_job(job_id)["cancel_requested"]:
                    raise asyncio.CancelledError
                if state["phase"] == "tools":
                    while state["call_index"] < len(state["calls"]):
                        call = state["calls"][state["call_index"]]
                        tool_started = row(
                            "SELECT id FROM tool_results WHERE job_id=? AND call_id=?",
                            (job_id, call["id"]),
                        )
                        if tool_started is None:
                            agent_event(
                                job_id,
                                "tool_start",
                                tool=call["name"],
                                call_id=call["id"],
                            )
                            with DB:
                                execute(
                                    "INSERT INTO tool_results(job_id,call_id,result)"
                                    " VALUES(?,?,NULL)",
                                    (job_id, call["id"]),
                                )
                        saved = row(
                            "SELECT result FROM tool_results WHERE job_id=? AND call_id=?",
                            (job_id, call["id"]),
                        )
                        if saved["result"] is not None:
                            result = decode(saved["result"])
                        else:
                            try:
                                result = await perform_tool(job_id, call)
                            except asyncio.CancelledError:
                                raise
                            except Exception as error:
                                result = {"ok": False, "error": str(error)}
                            with DB:
                                execute(
                                    "UPDATE tool_results SET result=?"
                                    " WHERE job_id=? AND call_id=?",
                                    (encode(result), job_id, call["id"]),
                                )
                            agent_event(
                                job_id,
                                "tool_result",
                                tool=call["name"],
                                call_id=call["id"],
                                ok=not (
                                    isinstance(result, dict)
                                    and (
                                        result.get("ok") is False
                                        or result.get("isError") is True
                                    )
                                ),
                            )
                        if call.get("modern"):
                            response_message = {
                                "role": "tool",
                                "tool_call_id": call["id"],
                                "content": encode(result),
                            }
                        else:
                            response_message = {
                                "role": "function",
                                "name": call["name"],
                                "content": encode(result),
                            }
                        state["messages"].append(response_message)
                        state["call_index"] += 1
                        set_state(job_id, state)
                    state["phase"] = "model"
                    apply_redirections(job_id, state)
                    if require_job(job_id)["text"]:
                        append_delta(job_id, "\n\n")
                    set_state(job_id, state)
                elif state["phase"] == "final":
                    if apply_redirections(job_id, state):
                        state["phase"] = "model"
                        append_delta(job_id, "\n\n")
                        set_state(job_id, state)
                    else:
                        finish_job(job_id, "completed")
                        return
                else:
                    apply_redirections(job_id, state)
                    await stream_model(job_id, state)
    except asyncio.CancelledError:
        if STOPPING:
            with DB:
                execute(
                    "UPDATE jobs SET status='queued',updated=? WHERE id=? AND status NOT IN"
                    " ('completed','cancelled','failed')",
                    (timestamp(), job_id),
                )
            raise
        await cancel_remote_executions(job_id)
        finish_job(job_id, "cancelled")
    except Exception as error:
        finish_job(job_id, "failed", str(error))
    finally:
        TASKS.pop(job_id, None)


def start_job(job_id):
    if job_id in TASKS:
        return
    TASKS[job_id] = asyncio.create_task(run_job(job_id))


def ensure_conversation(conversation_id=None, title="Beszélgetés"):
    conversation_id = conversation_id or identifier()
    with DB:
        execute(
            "INSERT OR IGNORE INTO conversations"
            "(id,title,messages,ui,sandbox_id,created,updated)"
            " VALUES(?,?, '[]','{}',NULL,?,?)",
            (conversation_id, title, timestamp(), timestamp()),
        )
    return conversation_id


def create_job_record(body, start=True):
    messages = normalize_messages(body.get("messages", []))
    last_user = next(
        (message for message in reversed(messages) if message["role"] == "user"),
        messages[-1],
    )
    title = body.get("title") or message_text(last_user["content"])[:100] or "Feladat"
    conversation_id = ensure_conversation(body.get("conversation_id"), title)
    job_id = identifier()
    mode = body.get("mode", "chat")
    if mode not in {"chat", "work"}:
        raise HTTPException(422, "A mód csak chat vagy work lehet.")
    with DB:
        execute(
            "INSERT INTO jobs"
            "(id,conversation_id,mode,title,status,context,state,text,reasoning,error,"
            "cancel_requested,created,updated)"
            " VALUES(?,?,?,?, 'queued',?,NULL,'','',NULL,0,?,?)",
            (
                job_id,
                conversation_id,
                mode,
                title,
                encode(messages),
                timestamp(),
                timestamp(),
            ),
        )
        execute(
            "UPDATE conversations SET messages=?,updated=? WHERE id=?",
            (encode(messages), timestamp(), conversation_id),
        )
    event(
        job_id,
        {
            "type": "meta",
            "job_id": job_id,
            "conversation_id": conversation_id,
            "mode": mode,
        },
    )
    if start:
        start_job(job_id)
    return job_snapshot(job_id)


def create_automated_work(prompt, title, suffix=""):
    content = prompt + suffix
    return create_job_record(
        {
            "mode": "work",
            "title": title,
            "messages": [{"role": "user", "content": content}],
        }
    )


async def scheduler_loop():
    while True:
        due = rows(
            "SELECT * FROM schedules WHERE enabled=1 AND next_run<=? ORDER BY next_run,id",
            (timestamp(),),
        )
        for schedule in due:
            with DB:
                occurrence = row(
                    "SELECT job_id FROM schedule_runs WHERE schedule_id=? AND due=?",
                    (schedule["id"], schedule["next_run"]),
                )
                if occurrence is None:
                    snapshot = create_job_record(
                        {
                            "mode": "work",
                            "title": schedule["title"],
                            "messages": [
                                {"role": "user", "content": schedule["prompt"]}
                            ],
                        },
                        start=False,
                    )
                    execute(
                        "INSERT INTO schedule_runs(schedule_id,due,job_id) VALUES(?,?,?)",
                        (schedule["id"], schedule["next_run"], snapshot["job_id"]),
                    )
                    scheduled_job_id = snapshot["job_id"]
                else:
                    scheduled_job_id = occurrence["job_id"]
                interval = schedule["interval_seconds"]
                if interval is None:
                    execute(
                        "UPDATE schedules SET enabled=0 WHERE id=?", (schedule["id"],)
                    )
                else:
                    execute(
                        "UPDATE schedules SET next_run=? WHERE id=?",
                        (schedule["next_run"] + interval, schedule["id"]),
                    )
            start_job(scheduled_job_id)
        await asyncio.sleep(1)


