@asynccontextmanager
async def lifespan(application):
    global DB, LLM, HTTP, STOPPING, SCHEDULER_TASK
    STOPPING = False
    DATA.mkdir(parents=True, exist_ok=True)
    ARTIFACT_ROOT.mkdir(parents=True, exist_ok=True)
    UPLOAD_ROOT.mkdir(parents=True, exist_ok=True)
    if not FRONTEND_PATH.is_file():
        alternative = ROOT / "file-1.html"
        if not alternative.is_file():
            raise RuntimeError("Az eredeti index.html frontend nem található.")
    os.environ["ABLITERATION_API_KEY"]
    os.environ["INSTAVM_API_KEY"]
    DB = sqlite3.connect(DATA / "application.sqlite3", isolation_level="DEFERRED")
    DB.row_factory = sqlite3.Row
    DB.execute("PRAGMA journal_mode=WAL")
    DB.execute("PRAGMA synchronous=FULL")
    DB.executescript(SCHEMA)
    DB.commit()
    HTTP = httpx.AsyncClient(timeout=None, follow_redirects=True)
    LLM = AsyncOpenAI(
        api_key=os.environ["ABLITERATION_API_KEY"],
        base_url=ABLITERATION_BASE_URL,
        timeout=None,
        max_retries=0,
    )
    configurations = json.loads(os.environ.get("MCP_SERVERS_JSON", "{}"))
    for name, configuration in configurations.items():
        connection = MCPConnection(name, configuration)
        await connection.initialize()
        MCP_CLIENTS[name] = connection
        for tool in connection.tools:
            digest = hashlib.sha256(
                (name + "\0" + tool["name"]).encode()
            ).hexdigest()[:16]
            function_name = "app_" + digest
            MCP_TOOLS[function_name] = (name, tool["name"])
    for unfinished in rows(
        "SELECT id FROM jobs WHERE status IN ('queued','running') ORDER BY created,id"
    ):
        start_job(unfinished["id"])
    SCHEDULER_TASK = asyncio.create_task(scheduler_loop())
    try:
        yield
    finally:
        STOPPING = True
        SCHEDULER_TASK.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await SCHEDULER_TASK
        active = list(TASKS.values())
        for task in active:
            task.cancel()
        if active:
            await asyncio.gather(*active, return_exceptions=True)
        await LLM.close()
        await HTTP.aclose()
        DB.commit()
        DB.close()
        VM_CLIENTS.clear()
        VM_LOCKS.clear()
        CONVERSATION_LOCKS.clear()
        MCP_CLIENTS.clear()
        MCP_TOOLS.clear()


