    if(expectedConversation && snapshot.conversation_id !== expectedConversation) return;
    var message = suppliedMessage || messages.find(function(item){return item.jobId === jobId;});
    if(!message){
      message = {
        role: "assistant",
        content: "",
        thinking: "",
        timeline: [],
        thinkingOpen: false,
        thinkingManual: false,
        jobId: jobId
      };
      messages.push(message);
    }
    backendMessage = message;
    backendApplySnapshot(snapshot, message);
    if(snapshot.status !== "queued" && snapshot.status !== "running") return;
    var source = new EventSource("/api/jobs/" + encodeURIComponent(jobId) + "/events");
    backendSource = source;
    var lastEvent = 0;
    source.onmessage = function(received){
      if(backendSource !== source) return;
      var payload;
      try{payload = JSON.parse(received.data);}catch(error){backendError(error);return;}
      if(payload.type === "snapshot"){
        lastEvent = payload.cursor || 0;
        backendApplySnapshot(payload, message);
        return;
      }
      var sequence = Number(received.lastEventId || 0);
      if(sequence && sequence <= lastEvent) return;
      if(sequence) lastEvent = sequence;
      if(payload.type === "delta"){
        if(typeof payload.content === "string") message.content += payload.content;
        if(typeof payload.reasoning_content === "string") message.thinking += payload.reasoning_content;
