        return {role: message.role, content: messageContentForModel(message.content)};
      });
      var assistant = {
        role: "assistant",
        content: "",
        thinking: "",
        timeline: [],
        isStreaming: true,
        thinkingOpen: false,
        thinkingManual: false
      };
      messages.push(assistant);
      render();
      if(backendMode === "chat") setBusy(true);
      var snapshot = await backendRequest("/api/jobs", {
        method: "POST",
        body: JSON.stringify({
          conversation_id: conversationId,
          mode: backendMode,
          messages: modelMessages
        })
      });
      assistant.jobId = snapshot.job_id;
      assistant.workMode = snapshot.mode;
      persistCurrent();
      await backendAttach(snapshot.job_id, assistant);
      await backendRefreshWork();
    }catch(error){
      setBusy(false);
      messages.forEach(function(message){
        if(message.isStreaming && !message.jobId) message.isStreaming = false;
      });
      render();
      persistCurrent();
      backendError(error);
    }
  }

  async function backendRegenerate(){
