      var snapshot = await backendRequest("/api/jobs/" + encodeURIComponent(previous.jobId) + "/retry", {method:"POST"});
      previous.jobId = snapshot.job_id;
      previous.content = "";
      previous.thinking = "";
      previous.timeline = [];
      previous.artifacts = [];
      previous.isError = false;
      previous.isStreaming = true;
      await backendAttach(snapshot.job_id, previous);
