def frontend_source():
    path = FRONTEND_PATH if FRONTEND_PATH.is_file() else ROOT / "file-1.html"
    source = path.read_text(encoding="utf-8")
    replacements = {
        "function saveHistory(){": "function saveHistoryLocal(){",
        "function render(){": "function renderBase(){",
        "function newConversation(){": "function newConversationBase(){",
        "function loadConversation(id){": "function loadConversationBase(id){",
    }
    for old, new in replacements.items():
        if old not in source:
            raise RuntimeError("A frontend integrációs pontja nem található: " + old)
        source = source.replace(old, new, 1)
    start = source.find("  async function stopActiveBackendJob()")
    if start < 0:
        raise RuntimeError("A frontend backend-feladatkezelője nem található.")
    end_match = re.search(
        r"\s+textarea\.addEventListener\(\s*[\"']input[\"']",
        source[start:],
    )
    if end_match is None:
        raise RuntimeError("A frontend üzenetküldő integrációs pontja nem található.")
    end = start + end_match.start()
    source = source[:start] + BRIDGE + source[end:]
    return source


@app.get("/", response_class=HTMLResponse)
async def frontend():
    return HTMLResponse(frontend_source())


def conversation_ui(conversation):
    saved = decode(conversation["ui"], {})
    if not saved:
        saved = {
            "id": conversation["id"],
            "conversation_id": conversation["id"],
            "title": conversation["title"],
            "messages": decode(conversation["messages"], []),
            "branches": [],
            "updated": int(conversation["updated"] * 1000),
            "pinned": False,
        }
    saved["conversation_id"] = conversation["id"]
    saved["title"] = conversation["title"]
    saved["updated"] = max(
        int(saved.get("updated", 0)), int(conversation["updated"] * 1000)
    )
    return saved


def merge_history(body):
    entries = body.get("conversations", [])
    if not isinstance(entries, list):
        raise HTTPException(422, "Érvénytelen beszélgetéslista.")
    with DB:
        for entry in entries:
            if not isinstance(entry, dict) or not entry.get("id"):
                raise HTTPException(422, "Érvénytelen beszélgetés.")
            conversation_id = entry.get("conversation_id") or entry["id"]
            title = str(entry.get("title", "Beszélgetés"))
            ensure_conversation(conversation_id, title)
            execute(
                "UPDATE conversations SET title=?,ui=?,updated=? WHERE id=?",
                (title, encode(entry), timestamp(), conversation_id),
            )
    return {"saved": len(entries)}


