@app.delete("/api/conversations/{conversation_id}")
async def delete_conversation(conversation_id: str):
    conversation = require_conversation(conversation_id)
    active = rows(
        "SELECT id FROM jobs WHERE conversation_id=? AND status IN ('queued','running')",
        (conversation_id,),
    )
    for job in active:
        await request_cancellation(job["id"])
    pending = [TASKS[job["id"]] for job in active if job["id"] in TASKS]
    if pending:
        await asyncio.gather(*pending, return_exceptions=True)
    if conversation["sandbox_id"]:
        lock = VM_LOCKS.setdefault(conversation_id, asyncio.Lock())
        async with lock:
            client = VM_CLIENTS.pop(conversation_id, None)
            if client is None:
                client = await asyncio.to_thread(construct_vm, conversation["sandbox_id"])
            await asyncio.to_thread(client.close_session)
    artifact_paths = rows(
        "SELECT path,site_root FROM artifacts WHERE conversation_id=?", (conversation_id,)
    )
    upload_paths = rows(
        "SELECT path FROM uploads WHERE conversation_id=?", (conversation_id,)
    )
    with DB:
        for job in rows("SELECT id FROM jobs WHERE conversation_id=?", (conversation_id,)):
            for table in ("events", "executions", "tool_results", "redirections"):
                execute("DELETE FROM " + table + " WHERE job_id=?", (job["id"],))
        execute("DELETE FROM artifacts WHERE conversation_id=?", (conversation_id,))
        execute("DELETE FROM uploads WHERE conversation_id=?", (conversation_id,))
        execute("DELETE FROM jobs WHERE conversation_id=?", (conversation_id,))
        execute("DELETE FROM conversations WHERE id=?", (conversation_id,))
    for record in artifact_paths:
        directory = Path(record["path"]).parent
        if directory.exists():
            for item in sorted(directory.rglob("*"), key=lambda value: len(value.parts), reverse=True):
                if item.is_file() or item.is_symlink():
                    item.unlink()
                elif item.is_dir():
                    item.rmdir()
            directory.rmdir()
    for record in upload_paths:
        Path(record["path"]).unlink(missing_ok=True)
    return {"deleted": True}


