async def server_events(job_id, request):
    snapshot = job_snapshot(job_id)
    cursor = snapshot["cursor"]
    yield "id: " + str(cursor) + "\ndata: " + encode(snapshot) + "\n\n"
    if snapshot["status"] in TERMINAL:
        return
    while True:
        if await request.is_disconnected():
            return
        batch = rows(
            "SELECT id,payload FROM events WHERE job_id=? AND id>? ORDER BY id",
            (job_id, cursor),
        )
        for record in batch:
            cursor = record["id"]
            yield "id: " + str(cursor) + "\ndata: " + record["payload"] + "\n\n"
        current = require_job(job_id)
        if current["status"] in TERMINAL:
            remaining = row(
                "SELECT id FROM events WHERE job_id=? AND id>? ORDER BY id LIMIT 1",
                (job_id, cursor),
            )
            if remaining is None:
                return
        if not batch:
            yield ": keepalive\n\n"
            await asyncio.sleep(0.5)


