def office_preview(path):
    suffix = path.suffix.lower()
    with zipfile.ZipFile(path) as archive:
        if suffix == ".docx":
            root = ElementTree.fromstring(archive.read("word/document.xml"))
            namespace = {"w": ""}
            paragraphs = []
            for paragraph in root.findall(".//w:p", namespace):
                text = "".join(
                    node.text or "" for node in paragraph.findall(".//w:t", namespace)
                )
                paragraphs.append("<p>" + html.escape(text) + "</p>")
            return "".join(paragraphs)
        if suffix == ".pptx":
            namespace = {"a": ""}
            files = [
                name
                for name in archive.namelist()
                if re.fullmatch(r"ppt/slides/slide\d+\.xml", name)
            ]
            files.sort(key=lambda name: int(re.search(r"slide(\d+)", name).group(1)))
            slides = []
            for index, name in enumerate(files, 1):
                root = ElementTree.fromstring(archive.read(name))
                text = [
                    node.text or "" for node in root.findall(".//a:t", namespace)
                ]
                slides.append(
                    "<section><h2>"
                    + str(index)
                    + ". dia</h2>"
                    + "".join("<p>" + html.escape(value) + "</p>" for value in text)
                    + "</section>"
                )
            return "".join(slides)
        if suffix == ".xlsx":
            namespace = {
                "s": "",
                "r": "",
            }
            shared = []
            if "xl/sharedStrings.xml" in archive.namelist():
                root = ElementTree.fromstring(archive.read("xl/sharedStrings.xml"))
                for item in root.findall("s:si", namespace):
                    shared.append(
                        "".join(node.text or "" for node in item.findall(".//s:t", namespace))
                    )
            workbook = ElementTree.fromstring(archive.read("xl/workbook.xml"))
            relationships = ElementTree.fromstring(
                archive.read("xl/_rels/workbook.xml.rels")
            )
            targets = {
                item.attrib["Id"]: item.attrib["Target"]
                for item in relationships
            }
            output = []
            for sheet in workbook.findall("s:sheets/s:sheet", namespace):
                relationship = sheet.attrib[
                    "{"
                ]
                target = targets[relationship]
                name = target.lstrip("/") if target.startswith("/") else "xl/" + target
                root = ElementTree.fromstring(archive.read(name))
                output.append("<h2>" + html.escape(sheet.attrib["name"]) + "</h2><table>")
                for sheet_row in root.findall(".//s:sheetData/s:row", namespace):
                    cells = {}
                    largest = 0
                    for cell in sheet_row.findall("s:c", namespace):
                        coordinate = cell.attrib.get("r", "A1")
                        letters = re.match(r"[A-Z]+", coordinate).group(0)
                        index = 0
                        for letter in letters:
                            index = index * 26 + ord(letter) - 64
                        largest = max(largest, index)
                        value_node = cell.find("s:v", namespace)
                        value = value_node.text if value_node is not None else ""
                        if cell.attrib.get("t") == "s" and value:
                            value = shared[int(value)]
                        elif cell.attrib.get("t") == "inlineStr":
                            value = "".join(
                                node.text or ""
                                for node in cell.findall(".//s:t", namespace)
                            )
                        elif not value:
                            formula = cell.find("s:f", namespace)
                            if formula is not None:
                                value = "=" + (formula.text or "")
                        cells[index] = value or ""
                    output.append(
                        "<tr>"
                        + "".join(
                            "<td>" + html.escape(cells.get(index, "")) + "</td>"
                            for index in range(1, largest + 1)
                        )
                        + "</tr>"
                    )
                output.append("</table>")
            return "".join(output)
    raise RuntimeError("Nem támogatott Office-előnézet.")


@app.get("/api/artifacts/{artifact_id}/preview")
async def preview_artifact(artifact_id: str):
    artifact = require_artifact(artifact_id)
    path = Path(artifact["path"])
    if artifact["kind"] == "site":
        return HTMLResponse(
            "<!doctype html><html><head><meta http-equiv='refresh' content='0;url="
            + "/api/artifacts/"
            + artifact_id
            + "/site/'></head><body>Site megnyitása</body></html>"
        )
    if path.suffix.lower() in {".docx", ".xlsx", ".pptx"}:
        body = await asyncio.to_thread(office_preview, path)
        body = (
            "<p>Natív fájl letöltése</p>"
            + body
        )
        return HTMLResponse(preview_page(artifact["name"], body))
    if artifact["mime"] == "application/pdf" or artifact["mime"].startswith("image/"):
        return FileResponse(path, media_type=artifact["mime"])
    if artifact["mime"].startswith("text/") or path.suffix.lower() in {
        ".json",
        ".md",
        ".py",
        ".js",
        ".css",
        ".csv",
    }:
        content = await asyncio.to_thread(path.read_text, encoding="utf-8")
        return HTMLResponse(
            preview_page(artifact["name"], "<pre>" + html.escape(content) + "</pre>")
        )
    return FileResponse(
        path, filename=artifact["name"], media_type=artifact["mime"]
    )


@app.get("/api/artifacts/{artifact_id}/site/")
@app.get("/api/artifacts/{artifact_id}/site/{asset_path:path}")
async def site_artifact(artifact_id: str, asset_path: str = ""):
    artifact = require_artifact(artifact_id)
    if not artifact["site_root"]:
        raise HTTPException(404, "Ez a fájl nem Site.")
    root = Path(artifact["site_root"]).resolve()
    path = (root / (asset_path or "index.html")).resolve()
    if not path.is_relative_to(root):
        raise HTTPException(404, "Az erőforrás nem található.")
    if path.is_dir():
        path = path / "index.html"
    if not path.is_file():
        raise HTTPException(404, "Az erőforrás nem található.")
    return FileResponse(path, media_type=mimetypes.guess_type(str(path))[0])


